"""Codex from actual data; report embeds raw Chromium screenshots byte-for-byte."""
from pathlib import Path
import json,re,html,base64,hashlib,ast
R=Path(__file__).resolve().parent.parent;J=lambda p:json.loads((R/p).read_text());e=lambda s:html.escape(str(s));sha=lambda b:hashlib.sha256(b).hexdigest()
C=J('report/CONTRATS_LEVEL_DESIGN_V114.json');assert C['validation']['ok'];n=C['counts']
old=ast.parse((R/'tools/build-docs-v113.py').read_text());STYLE=next(ast.literal_eval(t.value) for t in old.body if isinstance(t,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='STYLE' for x in t.targets))
STYLE+=' .badge{font:11px monospace;color:#c8b680} .entry{padding:22px;border:1px solid #405e57;margin:15px 0;background:#152722} .muted{color:#98afa4}.source{font-size:12px}.filterable[hidden]{display:none!important}.room table{font-size:11px} .legend{font:12px monospace;color:#a9bcb0} figure{break-inside:avoid}'
def page(title,b,js=''):return f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><style>{STYLE}</style></head><body><main>{b}</main>{js}</body></html>'
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+e(h)+'</th>'for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(v)+'</td>'for v in row)+'</tr>'for row in rows)+'</tbody></table>'
def metrics(rows):return '<div class="metrics">'+''.join(f'<div class="metric"><strong>{e(v)}</strong><small>{e(k)}</small></div>'for v,k in rows)+'</div>'
def svg(r):
 out=[f'<svg class="diagram" viewBox="-25 -32 {r["width"]+50} {r["depth"]+70}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Schéma calculé, non capture : {e(r["title"])}"><rect width="{r["width"]}" height="{r["depth"]}" fill="#102a2a" stroke="#95b4a6"/>']
 for b in r['solids']:
  col='#bcab74' if b['id'].startswith('vestibule:') else '#718e92' if b.get('material')=='glass' else '#446b5b'
  out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="{col}" fill-opacity=".6" stroke="#aabbb0"/>')
 for b in r['doors']+r['hatches']:out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="#b6724866" stroke="#dbb477"/>')
 for c in r['controls']:out.append(f'<circle cx="{c["x"]}" cy="{c["z"]}" r="8" fill="#bbe0b5"/>')
 for x in r['exits']:out.append(f'<circle cx="{x["x"]}" cy="{x["z"]}" r="12" fill="#233a34" stroke="#ecdbaf"/><text x="{max(55,min(1200,x["x"]-85))}" y="{max(20,x["z"]-19)}" fill="#dfd6ba" font-size="11">{e(x["label"])}</text>')
 return ''.join(out)+'</svg>'
rules=[(m[1],m[2].strip())for m in re.findall(r'^### (\d+) — (.+)\n+([\s\S]*?)(?=\n##|\Z)',(R/'CODEX_LEVEL_DESIGN_V113.md').read_text(),re.M)if int(m[0])<=60];assert len(rules)==60
rules[0]=('Une présence de lieu n’est pas une campagne terminée','V114 poursuit les dix lieux V113, ajoute quinze inspections et deux détours à l’opération locale. Vingt raccords réciproques, onze lieux d’opération et cinq objectifs locaux. Ne pas confondre un espace inspectable, un transport non joué et une séquence de film réellement adaptée.')
rules[34]=('Migrer les états, pas dupliquer les réserves','V113 est validée par son importeur réel avant conversion. Mondes connus, vies, chargeurs et anciens systèmes sont conservés ; la géométrie est remplacée par le catalogue courant vérifié. Aucun stock secondaire n’est donné. Un acteur placé dans un nouveau support est refusé sans téléportation de réparation. La reprise reste en pause.')
rules += [
('Atlas de fidélité avant les pourcentages','Vingt-huit repères explicitement nommés sont suivis, vingt associés à un lieu et huit encore absents. Cet atlas n’est pas un relevé exhaustif de chaque plan du film. Aucune fiche absente ne compte comme une scène jouée.'),
('Ne pas confondre cinéma, édition longue et extension de jeu','Chaque entrée indique film, Special Edition ou adaptation locale. La galerie logistique, la réserve, la maintenance et la dérivation optique sont des aménagements de gameplay. Les sentinelles de l’édition longue ne rendent pas obligatoire un nombre inventé de tourelles.'),
('Pas de porte entre des planètes','Gateway, préparation du Sulaco et réseau du processeur sont des ensembles d’inspection séparés. Le dropship, l’APC, la plateforme et le hangar final ne sont pas raccordés par une porte magique. Le transport reste déclaré absent tant qu’il n’est pas réellement simulé.'),
('Une porte doit appartenir à une paroi','Les vingt-cinq portes intérieures sont vérifiées entre leurs segments de paroi, ou sur une limite critique prévue. Chaque face des vingt liaisons reçoit deux retours physiques vers le périmètre : quarante vestibules et quatre-vingts retours. Le dessin reprend leurs volumes ; ne pas habiller une dalle isolée avec un simple écriteau.'),
('Arrivées et seuils contrôlés avec le gabarit réel','Les arrivées restent libres et raccordées. Un battant fermé bloque le seuil mais pas sa zone de regroupement intérieure. Les postes tactiques ne peuvent pas réserver un passage. Tester les deux sens, portes ouvertes et fermées, et ne pas retirer les collisions pour faciliter un pilote.'),
('Regrouper en file au vestibule','Le suivi normal reste réparti. Pour un transfert, les réservations suivent l’axe intérieur du vestibule avec des intervalles réels. Un compagnon ne doit pas chercher une formation latérale de l’autre côté d’un mur de retour. La marche et l’évitement demeurent simulés ; le transfert reste discret.'),
('Ripley n’est pas une Marine anonyme','La combinaison gris-bleu et les boucles brunes distinguent Ripley. Le casque et l’armure USCM ne lui sont pas attribués par défaut. À Gateway la fonction de tir est désactivée, indépendamment de l’affichage du modèle.'),
('Lire un membre à sa tenue et à son équipement','Hicks : armure et cœur, cartouches ; Hudson : casque/caméra et tracker ; Vasquez : bandana rouge, bras et oculaire ; Drake : couvre-chef et smartgun. Les figures restent stylisées, pas des scans de visages. Un marquage ne suffit pas à certifier une ressemblance 1:1.'),
('Les civils et synthétiques gardent leur rôle','Burke demeure civil et non armé. Bishop porte une combinaison claire et n’est pas un soldat lourd. Gorman, Ferro, Spunkmeyer et les corpsmen ont des équipements distincts. Les douze PNJ de briefing ne sont pas des renforts ajoutés à la population de combat.'),
('La distribution dépend du moment de l’histoire','Newt n’apparaît pas au réveil de la section. Les inspections du processeur ne promènent pas automatiquement le trio Hicks/Hudson/Ripley dans le final. L’opération locale réunissant Hudson et Newt reste une adaptation tactique, pas la chronologie fidèle du film.'),
('Une arme implique une mécanique et une réserve','Huit profils ont une fonction de tir/contact, une portée, une cadence et une réserve distinctes. Afficher un M56 dans un râtelier ne prouve pas que la totalité de la campagne l’utilise. Les capacités et dégâts sont des valeurs d’équilibrage du module, pas des spécifications filmées.'),
('Un râtelier n’est pas un menu gratuit','La caisse de maintenance donne M240 et trois grenades sous-canon après 1,05 seconde. L’armurerie en inspection permet des essais des huit profils. L’accès dépend de la portée et des obstacles ; interruption et import à mi-collecte ne donnent pas une seconde dotation.'),
('Les tirs secondaires partagent les murs du M41A','Pistolet, shotgun, smartgun, flammes et couteau utilisent les mêmes volumes projectile. Le shotgun répartit sept impacts pour une seule cartouche. Aucun objet opaque ne devient transparent parce que l’arme a changé.'),
('Les grenades menacent aussi leur lanceur','Le lancer consomme à son départ, puis simule un trajet temporel et une résolution locale. Une fermeture peut l’arrêter. Le souffle est occulté et peut atteindre Ripley, ses alliés ou Newt ; le joueur doit choisir une trajectoire sûre. Aucun rebond ni destruction de mur n’est simulé.'),
('La trajectoire persiste sans être recalculée depuis la visée','Position de départ, point engagé, horodatages et identifiant sont sauvegardés. Une reprise en pause ne détonne pas ni ne duplique une grenade. Les bornes, durées et identités sont vérifiées. La géométrie mobile intervient à la progression suivante.'),
('Le M240 est une projection courte, pas un feu infini','Le carburant est fini et indépendant du M41A. Le cône court est découpé par les murs. La version V114 applique le contact de flamme, pas une combustion persistante de résine ni une réaction spécifique complète de la Reine.'),
('Le smartgun aide la visée sans tirer à travers les parois','L’assistance est étroite, limitée à une cible reconnue dans la portée et une ligne dégagée. Le harnais et l’oculaire sont représentés pour les smartgunners. Les essais libres de Ripley avec M56 sont explicitement hors chronologie.'),
('Hicks garde un secondaire, Newt n’en reçoit jamais','Hicks neuf possède six cartouches de shotgun ; passer d’une arme à l’autre ne recharge rien. Une migration V113 ne lui offre pas ces six cartouches. Newt n’a ni sélecteur, ni réserve secondaire, ni animation de tir.'),
('Les supports des armes font partie du décor','Le M56 du banc repose horizontalement sur sa table, pas sur un faux mur flottant qui cache la section. Les râteliers muraux et cadres d’armure sont fixés aux emprises. Les cloisons de premier plan peuvent être atténuées visuellement sans retirer leurs collisions.'),
('Prouver la fidélité par état et captures, pas par annonce','Regrouper les écarts connus dans le Codex : plans interprétés, façades/extérieurs manquants, ascenseurs et transports non joués, boss et final absents. Joindre des captures non retouchées du HTML testé, avec origine des exports de scène. La fusion native et les sprites définitifs ne sont pas revendiqués.')
];assert len(rules)==80
lead='V114 — Lieux et identités. Branche autonome V113 poursuivie ; ce Codex suit la fidélité sans prétendre à une reproduction intégrale 1:1. Les inspections, les cinq objectifs locaux et les scènes manquantes restent séparés.'
body='<p class="kicker">Aliens 1986 / Codex de conception / V114 RC1</p><h1>Lieux et identités</h1><p class="lead">'+e(lead)+'</p>'+metrics([(25,'lieux inspectables'),(11,'lieux de l’opération'),(20,'raccords réciproques'),(8,'profils d’arme'),(16,'identités graphiques')])
body+='<nav><a href="#atlas">Atlas de présence</a><a href="#cast">Distribution</a><a href="#weapons">Armes</a><a href="#rules">80 règles</a><a href="#rooms">25 plans</a><a href="#sources">Sources</a></nav><input id="search" type="search" placeholder="Rechercher un lieu, support, personnage ou règle…" aria-label="Filtrer le Codex"><p id="found" class="small"></p>'
body+='<div class="callout">Les 202 solides fixes, les 25 portes intérieures et les 40 faces de liaison sont issus du même catalogue que la marche et les tirs. Les 135 props ne sont pas 135 sprites uniques. Le graphe est topologique : aucune distance inter-pièces n’est présentée comme un relevé de tournage.</div><h2 id="atlas">Atlas : présents, adaptés et absents</h2>'
md=['# CODEX V114 — Lieux et identités',lead,'## Atlas de référence']
for l in C['locations']:
 status='INSPECTION / SÉQUENCE ADAPTÉE' if l['rooms'] else 'ABSENT / RÉFÉRENCE SEULEMENT';names=[next(r['title'] for r in C['rooms'] if r['id']==i) for i in l['rooms']]
 body+=f'<section class="entry filterable"><span class="badge">{e(l["scope"])} · {e(status)}</span><h3>{e(l["name"])}</h3><p>{e(l["note"] or "Plan original adapté au jeu ; non métrique au film.")}</p><p class="small">{e(l["stage"])} · {e(l["link"])} · {e(" / ".join(names) or "Pas de salle livrée.")}</p></section>'
 md += [f'### {l["name"]}',f'{l["scope"]} / {status}. {l["note"]}', 'Lieux : '+(', '.join(l['rooms']) or 'aucun')]
body+='<h2 id="cast">Distribution et costumes</h2><p>Seize profils visuels ; douze PNJ nommés en tableaux de préparation, quatre membres connus du module. Les tenues sont des dessins procéduraux originaux. Ni les visages exacts des comédiens ni toutes les animations du film ne sont livrés.</p>'
for c in C['characters']:
 body+=f'<section class="entry filterable"><span class="badge">{e(c["role"])}</span><h3>{e(c["name"])}</h3><p>{e(c["notes"])}</p><p class="small">Tenue {e(c["wear"])} · {e(" / ".join(c["equipment"]))}</p></section>'
 md += [f'### {c["name"]}',c['notes'],'Tenue : '+c['wear']+' ; équipement : '+', '.join(c['equipment'])]
body+='<h2>Continuité : ne pas promettre la chronologie native</h2>'+table(['Moment','Règle'],[(b['beat'],b['rule'])for b in C['continuity']])
body+='<h2 id="weapons">Armes et équipement : statut exact</h2>'+table(['Élément','Intégration','Commande / limite'],[(q['name'],q['status'],q['command'])for q in C['equipment']])
body+='<p>Les chiffres ci-dessous sont ceux du module, en unités de jeu. Ils ne sont ni une fiche balistique réelle ni une affirmation sur la capacité de l’accessoire du film.</p>'+table(['Arme','Portée','Cadence minimale (s)','Dégât de base','Réserve'],[(w['name'],w['range'],w['cooldown'],w['damage'],w['resource']or'sans munitions')for w in C['weapons'].values()])
md+=['## Équipement']+[f'- {q["name"]} : {q["status"]} ; {q["command"]}.'for q in C['equipment']]
body+='<h2 id="rules">80 règles applicables</h2>';md+=['## Règles de conception']
for i,(title,text) in enumerate(rules,1):
 body+=f'<section class="filterable"><h3>{i:02} — {e(title)}</h3><p>{e(text)}</p></section>';md+=[f'### {i} — {title}',text]
body+='<h2 id="rooms">25 fiches géométriques</h2><p class="legend">Plans calculés, non captures. Vert : volumes fixes ; ambre : retours de vestibule ; contours dorés : portes et sas ; cercles : commandes et extrémités. Ces schémas ne représentent pas la perspective artistique du renderer.</p>'
for r in C['rooms']:
 local=[a for a in C['architecture']['doors'] if a['roomId']==r['id']];body+=f'<article class="room filterable"><span class="badge">{e(r["id"])} · {"OPÉRATION + INSPECTION"if r["connectedOperation"]else"INSPECTION, PAS OBJECTIF D’OPÉRATION"}</span><h2>{e(r["title"])}</h2><p>{e(r["goal"])}</p>'+svg(r)+table(['Ouverture','Support vérifié'],[(d['id'],', '.join(d['supportIds'])or'limite extérieure critique')for d in local])+table(['Face / destination','Seuil','Arrivée'],[(x['id']+' → '+x['to']['room'],f'{x["x"]}, {x["z"]}',str(x['arrival']))for x in r['exits']])+table(['Prop','Type','Support / élévation'],[(p['id'],p['type'],p.get('supportId')or p.get('bodyId')or p.get('support','')+f' · {p.get("elevation",0)}')for p in r['props']])+'</article>'
 md+=[f'## {r["title"]}',f'ID : {r["id"]}. Famille {r["family"]}. {r["goal"]}',f'Solides : {len(r["solids"])} ; portes : {len(r["doors"])} ; props : {len(r["props"])}.',*['Raccord : '+x['id']+' → '+x['to']['room']+' ; arrivée '+str(x['arrival'])for x in r['exits']],*['Support : '+p['id']+' / '+p.get('supportId',p.get('bodyId',p.get('support','—')))for p in r['props']]]
body+='<h2 id="sources">Sources et portée</h2><p>Références de film, accessoires de production et produits sous licence. Aucune image extraite, bande-son ou dialogue intégral n’est redistribué. Les données de scène et les tracés sont originaux ; les désignations de décor servent de repères.</p>'
for s in C['sources']:body+=f'<p class="source"><a href="{e(s["url"])}">{e(s["title"])}</a> — {e(s["use"])}</p>';md+=[f'{s["title"]} — {s["url"]} ({s["use"]})']
js='''<script>const q=document.getElementById('search'),a=[...document.querySelectorAll('.filterable')];q.addEventListener('input',()=>{let n=0;for(const x of a){x.hidden=!x.textContent.toLowerCase().includes(q.value.toLowerCase());if(!x.hidden)n++}document.getElementById('found').textContent=n+' entrées correspondantes';});</script>'''
(R/'CODEX_LEVEL_DESIGN_V114.html').write_text(page('Codex Aliens V114',body,js));(R/'CODEX_LEVEL_DESIGN_V114.md').write_text('\n\n'.join(md)+'\n')
