B=J('report/browser-results-v114.json');F=J('report/browser-fidelity-v114.json');h=sha((R/'JOUER_ALIENS_V114.html').read_bytes());assert B['htmlSha256']==h==F['htmlSHA256'];assert all(t['ok']for t in B['tests']+F['tests']);assert not B['pageErrors']+F['pageErrors'];assert not B['consoleErrors']+F['consoleErrors']
selection=['65_armurerie_ripley.png','67_vasquez_drake_dietrich.png','68_bishop_apone_gorman.png','69_hangar_preparation.png','70_gateway_burke.png','71_processeur_galeries.png','72_nurserie_inspection.png','73_mess_colonial.png','74_drain_newt.png','66_m240_essai.png','75_armement_paysage.png','76_repli_m240.png']
