node=int(re.search(r'# pass (\d+)',(R/'report/node-tests-v114.txt').read_text()).group(1));total=len(B['tests'])+len(F['tests']);reports=[]
report='<p class="kicker">Aliens 1986 / Rapport illustré / V114 RC1</p><h1>Reconnaître les lieux.<br>Conserver les preuves.</h1><p class="lead">Mise à niveau de l’architecture, des inspections historiques, des costumes et de l’armement dans la branche autonome V113.</p>'+metrics([(25,'inspections'),(8,'armes utilisables'),(node,'tests Node'),(total,'contrôles navigateur')])
report+='<div class="callout"><strong>Ce qui n’est pas revendiqué :</strong> reproduction intégrale 1:1, campagne native de 64 salles, plans métriques du tournage, acteurs photoréalistes, pilotage APC/dropship, ascenseurs et nouveau boss Reine. Les quinze inspections nouvelles ne sont pas quinze missions complètes. Le parcours de repli est une adaptation locale.</div><h2>Résultats concrets</h2><p>25 portes intérieures vérifiées et 40 vestibules raccordés au périmètre, 20 liaisons réciproques. Neuf variantes de l’opération terminent ; trois parcours d’inspection distincts traversent leurs raccords dans les deux sens. Les huit profils d’arme sont tirés par les contrôles du programme ; le M240 de maintenance est obtenu et utilisé au cours d’une nouvelle opération complète.</p><h2>Captures directes de Chromium</h2><p>Les douze PNG suivants sont embarqués byte-for-byte. Aucun dessin après coup, image générée, retouche ou remplacement du renderer. Les scènes tardives reprennent des exports intacts du pilote public ; l’origine est précisée à chaque image. Les graphismes restent procéduraux stylisés.</p>'
for i,name in enumerate(selection,1):
 x=lookup[name];p=R/'report/captures-v114'/name;raw=p.read_bytes();src=base64.b64encode(raw).decode();report+=f'<figure><h3>{i:02} — {e(captions[name])}</h3><img alt="{e(captions[name])}" src="data:image/png;base64,{src}"><figcaption>{e(x["origin"])}<br><span class="small">SHA-256 PNG : {sha(raw)}</span></figcaption></figure>';reports.append({'file':name,'sha256':sha(raw),'origin':x['origin']})
report+='<h2>Fidélité mesurée et prochaines lacunes</h2>'+table(['Présence vérifiée','Ce qui manque encore'],[('20 des 28 repères associés à un lieu','Narcissus, appartement Gateway, extérieur Hadley, plafond, conduits de repli, ascenseurs, famille Jorden et Derelict restent absents.'),('M41A, shotgun, M240, M56, pistolet, lance-grenades, grenade et couteau','Liaison dédiée de Bishop, bracelet, pilotage et duel P-5000 restent décor/fiche ou non joués.'),('16 profils, dont12NPC de briefing','Pas de visages exacts ou jeu d’animations de production. Chronologie locale assumée comme adaptée.')])
report+='<h2>Recette</h2><p>579 tests Node historiques réexécutés et 86 tests V114. Dix recettes navigateur historiques adaptées au nouveau contrat, plus une recette fidélité de '+str(len(F['tests']))+' contrôles. Les pilotes lisent l’état mais n’écrivent ni positions, vies, ressources ni objectifs ; leurs imports sont leurs exports non modifiés. Les tests dirigés sont séparés des parcours.</p><p class="small">HTML exécuté : '+h+'</p><p>Le rendu et l’exécution de ces octets sont testés dans Chromium. Le transport direct file:// n’est pas certifié dans l’environnement. Pas de push GitHub ou de déploiement Vercel.</p>'
